package com.kareem.lifeos;

import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.graphics.Color;
import android.os.Bundle;
import android.speech.RecognizerIntent;
import android.view.Gravity;
import android.view.View;
import android.view.inputmethod.EditorInfo;
import android.widget.EditText;
import android.widget.FrameLayout;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/** Golden-reference explicit interface to the LifeOS intelligence layer. */
public final class AskLifeOsActivity extends Activity {
    private static final int VOICE=51;private LinearLayout answers;private EditText input;private volatile boolean running;
    @Override public void onCreate(Bundle s){super.onCreate(s);render();}
    private void render(){
        LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(LifeOsUi.BG);
        LinearLayout head=new LinearLayout(this);head.setGravity(Gravity.CENTER_VERTICAL);head.setPadding(LifeOsUi.dp(this,16),LifeOsUi.dp(this,8),LifeOsUi.dp(this,8),LifeOsUi.dp(this,5));TextView title=LifeOsUi.text(this,"Ask LifeOS",20.5f,LifeOsUi.TEXT);LifeOsUi.weight(title,700);head.addView(title,new LinearLayout.LayoutParams(0,-2,1));View history=LifeOsUi.iconTouch(this,LifeOsIconView.HISTORY,LifeOsUi.TEXT,20,38);history.setContentDescription("Recent questions");history.setOnClickListener(v->showHistory());head.addView(history,new LinearLayout.LayoutParams(LifeOsUi.dp(this,38),LifeOsUi.dp(this,38)));View more=LifeOsUi.iconTouch(this,LifeOsIconView.MORE,LifeOsUi.TEXT,19,36);more.setContentDescription("More");more.setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));head.addView(more,new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,38)));root.addView(head);
        ScrollView sc=new ScrollView(this);sc.setFillViewport(true);sc.setVerticalScrollBarEnabled(false);LinearLayout body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(LifeOsUi.dp(this,16),0,LifeOsUi.dp(this,16),LifeOsUi.dp(this,8));View orb=LifeOsUi.orb(this);body.addView(orb,new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,154)));TextView hello=LifeOsUi.text(this,"How can I help you?",22f,LifeOsUi.TEXT);LifeOsUi.weight(hello,700);hello.setGravity(Gravity.CENTER);body.addView(hello);TextView sub=LifeOsUi.text(this,"Ask. Plan. Decide. Do.",12f,LifeOsUi.MUTED);sub.setGravity(Gravity.CENTER);sub.setPadding(0,LifeOsUi.dp(this,4),0,LifeOsUi.dp(this,14));body.addView(sub);
        for(String q:new String[]{"What needs my attention today?","Summarize my conversations with Ahmed this week.","Find the latest gypsum board price and compare it.","What did I decide about the car?","Draft a reply to GLIO with my car details."})body.addView(promptRow(q));
        answers=new LinearLayout(this);answers.setOrientation(LinearLayout.VERTICAL);answers.setPadding(0,LifeOsUi.dp(this,6),0,0);body.addView(answers);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));
        LinearLayout composerWrap=new LinearLayout(this);composerWrap.setGravity(Gravity.CENTER_VERTICAL);composerWrap.setPadding(LifeOsUi.dp(this,14),LifeOsUi.dp(this,5),LifeOsUi.dp(this,14),LifeOsUi.dp(this,5));LinearLayout pill=new LinearLayout(this);pill.setGravity(Gravity.CENTER_VERTICAL);pill.setPadding(LifeOsUi.dp(this,15),0,LifeOsUi.dp(this,3),0);pill.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE_2,LifeOsUi.BORDER,24));input=new EditText(this);input.setHint("Ask anything…");input.setHintTextColor(LifeOsUi.MUTED);input.setTextColor(LifeOsUi.TEXT);input.setTextSize(12.2f);input.setSingleLine(true);input.setGravity(Gravity.CENTER_VERTICAL);input.setImeOptions(EditorInfo.IME_ACTION_SEND);input.setBackgroundColor(Color.TRANSPARENT);input.setPadding(0,0,0,0);pill.addView(input,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,46),1));View mic=LifeOsUi.iconTouch(this,LifeOsIconView.MIC,LifeOsUi.MUTED,18,36);mic.setContentDescription("Voice question");mic.setOnClickListener(v->startVoice());pill.addView(mic,new LinearLayout.LayoutParams(LifeOsUi.dp(this,36),LifeOsUi.dp(this,36)));composerWrap.addView(pill,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,48),1));FrameLayout send=new FrameLayout(this);send.setBackground(LifeOsUi.round(this,LifeOsUi.BLUE,LifeOsUi.BLUE,100));send.setElevation(LifeOsUi.dp(this,4));LifeOsIconView plane=new LifeOsIconView(this,LifeOsIconView.SEND,Color.WHITE);send.addView(plane,new FrameLayout.LayoutParams(LifeOsUi.dp(this,21),LifeOsUi.dp(this,21),Gravity.CENTER));send.setOnClickListener(v->ask(input.getText().toString()));LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(LifeOsUi.dp(this,46),LifeOsUi.dp(this,46));sp.setMargins(LifeOsUi.dp(this,7),0,0,0);composerWrap.addView(send,sp);input.setOnEditorActionListener((v,id,e)->{if(id==EditorInfo.IME_ACTION_SEND){ask(input.getText().toString());return true;}return false;});root.addView(composerWrap);root.addView(LifeOsUi.bottomNav(this,AskLifeOsActivity.class));setContentView(root);
    }
    private View promptRow(String q){LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(LifeOsUi.dp(this,12),LifeOsUi.dp(this,8),LifeOsUi.dp(this,11),LifeOsUi.dp(this,8));row.setMinimumHeight(LifeOsUi.dp(this,48));row.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE,LifeOsUi.BORDER,13));TextView text=LifeOsUi.text(this,q,11.5f,LifeOsUi.TEXT);text.setMaxLines(2);row.addView(text,new LinearLayout.LayoutParams(0,-2,1));row.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.TEXT,12),new LinearLayout.LayoutParams(LifeOsUi.dp(this,12),LifeOsUi.dp(this,22)));row.setOnClickListener(v->{input.setText(q);ask(q);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,0,0,LifeOsUi.dp(this,6));row.setLayoutParams(p);return row;}
    private void ask(String q){q=q==null?"":q.trim();if(q.isEmpty()||running)return;saveHistory(q);running=true;answers.removeAllViews();LinearLayout loading=LifeOsUi.card(this);loading.addView(LifeOsUi.text(this,"Thinking with your LifeOS memory…",10.5f,LifeOsUi.MUTED));answers.addView(loading);final String question=q;new Thread(()->{String answer;try{String context=LifeIntelligenceEngine.context(this,question);if(BackgroundModelManager.isReadyFast(this)){File model=BackgroundModelManager.modelFile(this);String prompt="You are LifeOS, Kareem's private personal intelligence. Answer the QUESTION using ONLY the grounded CONTEXT below. Address Kareem directly as 'you'; never say 'the user'. Be concise, useful and explicit about uncertainty. Do not invent missing facts. Maximum 8 short sentences.\nQUESTION:\n"+question+"\n\n"+context;answer=BackgroundSemanticRuntime.generateFreeform(this,model.getAbsolutePath(),prompt);}else answer=LifeIntelligenceEngine.fallbackAnswer(this,question);}catch(Throwable e){answer=LifeIntelligenceEngine.fallbackAnswer(this,question);}final String out=UserFacingText.humanize(answer);runOnUiThread(()->{running=false;answers.removeAllViews();LinearLayout card=LifeOsUi.card(this);TextView k=LifeOsUi.text(this,"LIFE INTELLIGENCE",9f,LifeOsUi.BLUE);LifeOsUi.weight(k,700);card.addView(k);TextView a=LifeOsUi.text(this,out,11.5f,LifeOsUi.TEXT);a.setPadding(0,LifeOsUi.dp(this,6),0,0);card.addView(a);answers.addView(card);});},"lifeos-ask").start();}
    private void showHistory(){answers.removeAllViews();List<String> xs=history();if(xs.isEmpty()){answers.addView(LifeOsUi.text(this,"No recent questions yet.",11f,LifeOsUi.MUTED));return;}TextView h=LifeOsUi.text(this,"Recent questions",12.5f,LifeOsUi.TEXT);LifeOsUi.weight(h,700);h.setPadding(0,0,0,LifeOsUi.dp(this,6));answers.addView(h);for(String q:xs){LinearLayout r=new LinearLayout(this);r.setGravity(Gravity.CENTER_VERTICAL);r.setPadding(LifeOsUi.dp(this,10),0,LifeOsUi.dp(this,9),0);r.setBackground(LifeOsUi.round(this,LifeOsUi.SURFACE,LifeOsUi.BORDER,12));TextView t=LifeOsUi.text(this,q,11f,LifeOsUi.TEXT);r.addView(t,new LinearLayout.LayoutParams(0,LifeOsUi.dp(this,40),1));r.addView(LifeOsUi.icon(this,LifeOsIconView.CHEVRON,LifeOsUi.MUTED,11),new LinearLayout.LayoutParams(LifeOsUi.dp(this,11),LifeOsUi.dp(this,18)));r.setOnClickListener(v->{input.setText(q);ask(q);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,LifeOsUi.dp(this,40));p.setMargins(0,0,0,LifeOsUi.dp(this,5));answers.addView(r,p);}}
    private void saveHistory(String value){String s=value==null?"":value.trim();if(s.isEmpty())return;ArrayList<String> h=new ArrayList<>(history());h.remove(s);h.add(0,s);while(h.size()>6)h.remove(h.size()-1);prefs().edit().putString("history",android.text.TextUtils.join("\u001f",h)).apply();}
    private List<String> history(){String raw=prefs().getString("history","");if(raw==null||raw.isEmpty())return new ArrayList<>();return new ArrayList<>(Arrays.asList(raw.split("\u001f")));}
    private SharedPreferences prefs(){return getSharedPreferences("lifeos_ask",MODE_PRIVATE);}
    private void startVoice(){try{Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);startActivityForResult(i,VOICE);}catch(Throwable ignored){}}
    @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(requestCode==VOICE&&resultCode==RESULT_OK&&data!=null){ArrayList<String> xs=data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(xs!=null&&!xs.isEmpty()){input.setText(xs.get(0));ask(xs.get(0));}}}
}
